// The settings modules generated by the app (MsfsUi.Core ConfigScript, kept as fixtures by ModContractTests) read by
// the mod's code, against the real catalogue. Run `node build/build.ts` first: it generates src/generated/catalog.ts.

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { CATALOG } from '../src/generated/catalog.ts';
import { defaultSettings, resolveSettings } from '../src/core/settings.ts';

async function fixture(name: string): Promise<unknown> {
  const module = (await import(`./fixtures/${name}`)) as { default: unknown };
  return module.default;
}

describe('config.js written by the app', () => {
  it('gives the catalogue defaults, without any problem', async () => {
    const result = resolveSettings(await fixture('config.defaults.js'), CATALOG);
    assert.deepEqual(result.problems, []);
    assert.equal(result.allDefaults, false);
    assert.deepEqual(result.values, defaultSettings(CATALOG));
  });

  it('carries the user choices to the mod', async () => {
    const result = resolveSettings(await fixture('config.custom.js'), CATALOG);
    assert.deepEqual(result.problems, []);
    assert.deepEqual(result.values.fastMenus, { enabled: true, speed: 3, instantImages: false });
    assert.equal(result.values.weatherBar!.enabled, false);
    assert.deepEqual(result.values.timeWheel, { enabled: true, step: 120, fastStep: 1800 });
    assert.equal(result.values.aircraftSetup!.widenColumn, 0);
  });
});
